<x-layouts.app :title="$chatbot->name"><x-page-header eyebrow="Rule-based chatbot" :title="$chatbot->name" :description="$chatbot->description ?: 'Automatic replies for an assigned WhatsApp session.'"><x-slot:actions><div class="flex flex-wrap gap-2">@if($tenantPermissions->contains('chatbots.update')&&$chatbot->status->value!=='archived')<a class="btn-secondary" href="{{ route('tenant.chatbots.edit',$chatbot) }}">Edit</a>@endif @if($tenantPermissions->contains('chatbots.publish')&&$chatbot->status->value==='draft')<form method="post" action="{{ route('tenant.chatbots.publish',$chatbot) }}">@csrf<button class="btn-primary">Publish</button></form>@endif @if($tenantPermissions->contains($chatbot->is_enabled?'chatbots.disable':'chatbots.enable')&&$chatbot->status->value==='published')<form method="post" action="{{ route('tenant.chatbots.toggle',$chatbot) }}">@csrf<button class="btn-secondary">{{ $chatbot->is_enabled?'Disable':'Enable' }}</button></form>@endif @if($tenantPermissions->contains('chatbots.archive'))<form method="post" action="{{ route($chatbot->status->value==='archived'?'tenant.chatbots.restore':'tenant.chatbots.archive',$chatbot) }}">@csrf<button class="btn-ghost">{{ $chatbot->status->value==='archived'?'Restore':'Archive' }}</button></form>@endif</div></x-slot:actions></x-page-header>
