<section class="panel mt-6 overflow-hidden"><h2 class="section-title">Rules</h2><div class="mt-4 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b text-[var(--text-muted)]"><th class="py-3">Priority</th><th>Name</th><th>Match</th><th>Action</th><th>Enabled</th></tr></thead><tbody>@foreach($chatbot->rules->sortBy('priority') as $rule)<tr class="border-b last:border-0"><td class="py-3">{{ $rule->priority }}</td><td>{{ $rule->name }}</td><td>{{ str($rule->match_type->value)->headline() }}</td><td>{{ str($rule->action_type->value)->headline() }}</td><td>{{ $rule->is_enabled?'Yes':'No' }}</td></tr>@endforeach</tbody></table></div></section>
